// The Palmetto Beat — RSS sources, each verified live on 2026-08-03.
//
// tier 1   = highest priority
// official = an authoritative city feed; bypasses the local-place-name test
//            (everything on it is Palmetto by definition)
//
// NOTE: palmettofl.org ModID=76 was tested and REMOVED — its channel is
// "Palmetto - Pages", a site directory listing ("Agendas", "Minutes",
// "Human Resources"), not News Flash. No News Flash RSS module exists on
// this site. Check palmettofl.org/m/NewsFlash manually — see docs/03-SOURCES.md.

return [
  { url: 'https://www.palmettofl.org/RSSFeed.aspx?ModID=58&CID=All-calendar.xml', source: 'City of Palmetto — Calendar', tier: 1, official: true },
  { url: 'https://www.palmettofl.org/RSSFeed.aspx?ModID=65&CID=All-0',      source: 'City of Palmetto — Agendas', tier: 1, official: true },
  { url: 'https://news.google.com/rss/search?q=%22City+of+Palmetto%22+OR+%22Palmetto+commission%22+when:14d&hl=en-US&gl=US&ceid=US:en', source: 'Google News — Palmetto government', tier: 1 },
  { url: 'https://news.google.com/rss/search?q=%22Palmetto%22+Florida+-%22Palmetto+Bay%22+when:7d&hl=en-US&gl=US&ceid=US:en', source: 'Google News — Palmetto FL', tier: 2 },
  { url: 'https://www.suncoastpost.com/feed/',                              source: 'The Suncoast Post', tier: 2 },
  { url: 'https://news.google.com/rss/search?q=%22Manatee+County%22+Florida+when:7d&hl=en-US&gl=US&ceid=US:en', source: 'Google News — Manatee County', tier: 3 },
  { url: 'https://www.mysuncoast.com/arc/outboundfeeds/rss/',               source: 'ABC7 WWSB / MySuncoast', tier: 3 },
  { url: 'https://thebradentonjournal.substack.com/feed',                   source: 'The Bradenton Journal', tier: 3 }
].map(json => ({ json }));

// Parse every feed and normalise to a flat item shape.
// NOTE: relies on 1:1 order alignment with 'Feed List'. 'Fetch Feed' is set to
// alwaysOutputData + continueRegularOutput so a dead feed still emits a slot and
// alignment is preserved.
const feeds = $('Feed List').all().map(i => i.json);

const strip = (s) => String(s ?? '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const tag = (block, name) => {
  const m = block.match(new RegExp('<' + name + '[^>]*>([\\s\\S]*?)<\\/' + name + '>', 'i'));
  return m ? strip(m[1]) : '';
};

const out = [];

for (let i = 0; i < items.length; i++) {
  const feed = feeds[i] || { source: 'unknown', tier: 3, official: false, url: '' };
  const xml = String(items[i].json?.data ?? items[i].json?.body ?? '');
  if (!xml || xml.indexOf('<') === -1) continue;

  // Handle both RSS <item> and Atom <entry>
  const blocks = xml.match(/<item[\s>][\s\S]*?<\/item>/gi) || xml.match(/<entry[\s>][\s\S]*?<\/entry>/gi) || [];

  for (const b of blocks) {
    const title = tag(b, 'title');
    if (!title) continue;

    let link = tag(b, 'link');
    if (!link) {
      const m = b.match(/<link[^>]*href="([^"]+)"/i);
      link = m ? m[1] : '';
    }

    const dateRaw = tag(b, 'pubDate') || tag(b, 'published') || tag(b, 'updated') || tag(b, 'dc:date');
    const parsed = dateRaw ? new Date(dateRaw) : null;
    const iso = parsed && !isNaN(parsed) ? parsed.toISOString() : null;

    const summary = (tag(b, 'description') || tag(b, 'summary') || tag(b, 'content')).slice(0, 600);

    out.push({
      json: {
        title,
        link,
        summary,
        publishedAt: iso,
        source: feed.source,
        tier: feed.tier,
        official: !!feed.official,
        dedupeKey: (tag(b, 'guid') || link || title).slice(0, 300)
      }
    });
  }
}

return out;

// Relevance filter, tuned against live feed output (2026-08-03).
// Kills the dominant noise classes: obituaries, real-estate listings,
// and the several other US towns also called Palmetto.
//
// TUNE THESE. If the draft feels thin, raise MAX_AGE_DAYS. If it feels
// noisy, raise MIN_SCORE.
const MAX_AGE_DAYS = 7;    // tier 2 / 3 — matches a twice-weekly issue
const TIER1_AGE_DAYS = 30; // civic notices stay relevant longer
const MIN_SCORE = 0;
const MAX_ITEMS = 60;

// Domains that are pure noise in these feeds
const BLOCK_DOMAINS = [
  'tributearchive.com', 'legacy.com', 'echovita.com', 'dignitymemorial.com',
  'findagrave.com', 'realtor.com', 'zillow.com', 'redfin.com', 'homes.com',
  'trulia.com', 'apartments.com', 'youtube.com', 'iqair.com', 'maxpreps.com'
];

// Title patterns that are noise regardless of source
const BLOCK_TITLE = [
  /\bobituar/i, /\bfuneral home\b/i, /\bin loving memory\b/i, /\bdeath notice\b/i,
  /\bfor sale\b/i, /\bopen house\b/i, /\bMLS\b/, /\bsq\.? ?ft\b/i,
  /^\d+\s+\w+.*,\s*(FL|Florida)\s*\d{5}/i,   // bare street-address listings
  /\bair quality index\b/i, /\bhoroscope\b/i
];

// Other "Palmetto"s that are NOT our Palmetto.
// Palmetto GA (Fulton County), Palmetto Bay FL, Palmetto Bluff SC,
// the Palmetto State (SC), and the insect.
const WRONG_PALMETTO = [
  /palmetto bay/i, /palmetto bluff/i, /palmetto state/i, /palmetto bug/i,
  /palmetto general/i, /palmetto, ?(ga|sc|georgia|south carolina)/i,
  /\bfulton county\b/i, /\bunion city\b/i, /\bpalmetto, ?tn\b/i,
  /palmetto moon/i, /palmetto health/i,
  // Miami-Dade: the Palmetto Expressway (SR 826), Palmetto Senior High,
  // and the Palmetto Panthers are all ~200 miles from us.
  /palmetto expressway/i, /palmetto panthers/i, /palmetto senior high/i,
  /\bmiami\b/i, /\bhialeah\b/i, /miami-dade/i
];

// Local place names that make a regional story ours
const LOCAL = /\b(palmetto|ellenton|manatee county|terra ceia|rubonia|memphis road|old memphis|10th street|8th avenue|riverside drive|green bridge|manatee river|palmetto high|lincoln middle|blackburn|snead island|sunshine skyway)\b/i;

const now = Date.now();
const out = [];
const dropped = { domain: 0, title: 0, wrongPalmetto: 0, stale: 0, notLocal: 0, lowScore: 0 };

for (const item of items) {
  const j = item.json;
  const hay = `${j.title} ${j.summary}`;
  const link = String(j.link || '').toLowerCase();

  // 1. cheap noise rejects first
  if (BLOCK_DOMAINS.some(d => link.includes(d))) { dropped.domain++; continue; }
  if (BLOCK_TITLE.some(re => re.test(j.title))) { dropped.title++; continue; }
  if (WRONG_PALMETTO.some(re => re.test(hay))) { dropped.wrongPalmetto++; continue; }

  // 2. recency — undated items are kept (city notices often have no date)
  const maxAge = (j.tier === 1 ? TIER1_AGE_DAYS : MAX_AGE_DAYS) * 86400000;
  if (j.publishedAt) {
    const age = now - new Date(j.publishedAt).getTime();
    if (age > maxAge || age < -86400000) { dropped.stale++; continue; }
  }

  // 3. relevance — only OFFICIAL city feeds bypass the local test.
  //    Google News tier-1 queries are searches, not authoritative sources,
  //    so they still have to name a local place.
  const isLocal = LOCAL.test(hay);
  if (!j.official && !isLocal) { dropped.notLocal++; continue; }

  // 4. score for ordering
  let score = 0;
  if (j.official) score += 60;
  else if (j.tier === 1) score += 40;
  if (/\bpalmetto\b/i.test(j.title)) score += 30;
  if (/\bellenton\b/i.test(hay)) score += 15;
  if (/\b(commission|CRA|council|ordinance|rezon|budget|permit|development|redevelop|annex)\b/i.test(hay)) score += 25;
  if (/\b(school|police|sheriff|fire|road|closure|water|utility|storm|hurricane|evacuat)\b/i.test(hay)) score += 15;
  if (/\b(opening|opens|new business|ribbon cutting|grand opening|restaurant|shop|store)\b/i.test(hay)) score += 12;
  if (/\b(festival|market|event|concert|parade|fair|cleanup)\b/i.test(hay)) score += 10;
  if (j.tier === 3) score -= 10;

  if (score < MIN_SCORE) { dropped.lowScore++; continue; }

  out.push({ json: { ...j, score, isLocal } });
}

console.log('Filter:', items.length, 'in ->', out.length, 'kept. Dropped:', JSON.stringify(dropped));

out.sort((a, b) => b.json.score - a.json.score);
return out.slice(0, MAX_ITEMS);

// Wrap the model output in a minimal HTML shell for readable review.
const raw = String($json.text ?? $json.response ?? $json.output ?? '')
  .replace(/^```html\s*/i, '')
  .replace(/```\s*$/,'')
  .trim();

const count = $('Build Prompt').first().json.count;
const stamp = new Date().toLocaleString('en-US', { timeZone: 'America/New_York' });

const html = `<!doctype html>
<html><head><meta charset="utf-8"><title>The Palmetto Beat — draft ${stamp}</title>
<style>body{font:16px/1.6 -apple-system,BlinkMacSystemFont,Segoe UI,Helvetica,Arial,sans-serif;max-width:640px;margin:40px auto;padding:0 20px;color:#1a1a1a}h1{font-size:24px;border-bottom:3px solid #1a1a1a;padding-bottom:8px}h2{font-size:18px;margin-top:32px;text-transform:uppercase;letter-spacing:.05em;color:#444}a{color:#0b6}.meta{color:#777;font-size:13px}</style>
</head><body>
<h1>The Palmetto Beat — DRAFT</h1>
<p class="meta">Generated ${stamp} · ${count} source items · NOT FOR PUBLICATION UNTIL VERIFIED</p>
${raw}
</body></html>`;

return [{ json: { html, count, stamp } }];

